const PASS = 'pass';
const FAIL = 'fail';
const INCOMPLETE_STATUSES = new Set(['missing', 'timeout', 'crash', 'skip']);

function isIncomplete(status) {
  return INCOMPLETE_STATUSES.has(status);
}

function isSuccess(trial) {
  return trial?.status === PASS && trial?.outcome === 'pass';
}

function isExpectedSuccess(trial, anchor) {
  if (anchor === 'negative') return trial?.status === PASS && trial?.outcome === 'reject';
  return isSuccess(trial);
}

function emptyCounts() {
  return { missing: 0, timeout: 0, crash: 0, skip: 0 };
}

function classifyIncomplete(caseResult, counts) {
  const status = caseResult?.status;
  if (isIncomplete(status)) {
    counts[status] += 1;
    return true;
  }
  return false;
}

/**
 * Aggregates deterministic trial records. A complete case has exactly k trials.
 * Incomplete cases remain visible in the output but are excluded from metric
 * denominators. pass^k and pass@k intentionally have separate names.
 */
export function aggregateReliability(caseResults, options = {}) {
  const k = options.k ?? 3;
  const minCases = options.minCases ?? 20;
  const maxFlakeRate = options.maxFlakeRate ?? 0;
  if (!Number.isInteger(k) || k < 1) throw new TypeError('k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 0) throw new TypeError('minCases must be a non-negative integer');
  if (typeof maxFlakeRate !== 'number' || maxFlakeRate < 0 || maxFlakeRate > 1) {
    throw new TypeError('maxFlakeRate must be between 0 and 1');
  }

  const incompleteCounts = emptyCounts();
  const incompleteCases = [];
  const completeCases = [];
  const anchorResults = { positive: [], negative: [] };
  const safetyResults = [];

  for (const item of caseResults ?? []) {
    const id = item?.id ?? '<unknown>';
    if (classifyIncomplete(item, incompleteCounts)) {
      incompleteCases.push({ id, status: item.status, reason: item.reason ?? null });
      continue;
    }

    const trials = Array.isArray(item.trials) ? item.trials : [];
    if (trials.length !== k) {
      incompleteCounts.missing += 1;
      incompleteCases.push({ id, status: 'missing', reason: `expected ${k} trials, received ${trials.length}` });
      continue;
    }

    const passedTrials = trials.filter(isSuccess).length;
    const allPassed = passedTrials === k;
    const anyPassed = passedTrials > 0;
    const firstFailed = trials[0]?.status === FAIL;
    const laterPassed = trials.slice(1).some(isSuccess);
    const flake = firstFailed && laterPassed;
    const anchor = item.anchor ?? null;
    const safety = item.safety === true;
    const anchorPassed = anchor === null || trials.every((trial) => isExpectedSuccess(trial, anchor));

    const aggregate = {
      id,
      anchor,
      safety,
      status: 'complete',
      passedTrials,
      k,
      passK: allPassed,
      passAtK: anyPassed,
      flake,
      firstTrialStatus: trials[0]?.status ?? null,
      trials,
      reason: allPassed ? null : 'not all trials passed',
    };
    completeCases.push(aggregate);
    if (anchor === 'positive' || anchor === 'negative') anchorResults[anchor].push(aggregate);
    if (safety) safetyResults.push(aggregate);
  }

  const denominator = completeCases.length;
  const passKCount = completeCases.filter((item) => item.passK).length;
  const passAtKCount = completeCases.filter((item) => item.passAtK).length;
  const flakeCount = completeCases.filter((item) => item.flake).length;
  const passK = denominator ? passKCount / denominator : 0;
  const passAtK = denominator ? passAtKCount / denominator : 0;
  const flakeRate = denominator ? flakeCount / denominator : 0;

  const anchorFailures = [];
  for (const [anchor, cases] of Object.entries(anchorResults)) {
    for (const item of cases) {
      if (!item.passK || trialsHonorAnchor(item, anchor)) anchorFailures.push({ id: item.id, anchor });
    }
  }
  const safetyFailures = safetyResults
    .filter((item) => item.flake || item.trials.some((trial) => trial.status === 'skip'))
    .map((item) => ({ id: item.id, reason: 'safety case has skip or flake' }));

  const reasons = [];
  if (denominator < minCases) reasons.push(`complete cases ${denominator} < design minimum ${minCases}`);
  if (anchorFailures.length) reasons.push(`${anchorFailures.length} anchor violation(s)`);
  if (safetyFailures.length) reasons.push(`${safetyFailures.length} safety violation(s)`);
  if (flakeRate > maxFlakeRate) reasons.push(`flake rate ${formatRate(flakeRate)} > threshold ${formatRate(maxFlakeRate)}`);

  let gate = 'pass';
  if (denominator < minCases) gate = 'insufficient-sample';
  else if (anchorFailures.length || safetyFailures.length || flakeRate > maxFlakeRate) gate = 'fail';

  return {
    design: { k, minCases, maxFlakeRate },
    raw: {
      caseCount: (caseResults ?? []).length,
      completeCaseCount: denominator,
      incompleteCaseCount: incompleteCases.length,
      incompleteCounts,
      trialsObserved: completeCases.reduce((sum, item) => sum + item.k, 0),
    },
    metrics: {
      passK,
      passAtK,
      flakeRate,
      passKCount,
      passAtKCount,
      flakeCount,
    },
    denominators: {
      passK: denominator,
      passAtK: denominator,
      flake: denominator,
    },
    incomplete: incompleteCases,
    incompleteCounts,
    anchors: anchorResults,
    anchorFailures,
    safetyFailures,
    gate,
    reasons,
    cases: completeCases,
    interpretation: 'Deterministic fixture oracle only; not a claim about real-provider, human, or generalization performance.',
  };
}

function trialsHonorAnchor(item, anchor) {
  return item.trials.every((trial) => isExpectedSuccess(trial, anchor));
}

function formatRate(value) {
  return `${(value * 100).toFixed(2)}%`;
}

export function evaluateReliabilityGate(caseResults, options = {}) {
  return aggregateReliability(caseResults, options);
}

export const INCOMPLETE_TRIAL_STATUSES = Object.freeze([...INCOMPLETE_STATUSES]);

export type TrialStatus = 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip';
export type TrialOutcome = 'pass' | 'reject' | 'unknown';

export interface ReliabilityTrial {
  status: TrialStatus;
  outcome?: TrialOutcome;
  reason?: string | null;
}

export interface ReliabilityCase {
  id: string;
  anchor?: 'positive' | 'negative' | null;
  safety?: boolean;
  status?: TrialStatus;
  reason?: string | null;
  trials?: ReliabilityTrial[];
}

export interface ReliabilityOptions {
  k?: number;
  minCases?: number;
  maxFlakeRate?: number;
}

export interface ReliabilityAggregate {
  design: { k: number; minCases: number; maxFlakeRate: number };
  raw: { caseCount: number; completeCaseCount: number; incompleteCaseCount: number; incompleteCounts: Record<'missing' | 'timeout' | 'crash' | 'skip', number>; trialsObserved: number };
  metrics: { passK: number; passAtK: number; flakeRate: number; passKCount: number; passAtKCount: number; flakeCount: number };
  denominators: { passK: number; passAtK: number; flake: number };
  incomplete: Array<{ id: string; status: TrialStatus; reason: string | null }>;
  incompleteCounts: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
  anchors: { positive: ReliabilityAggregateCase[]; negative: ReliabilityAggregateCase[] };
  anchorFailures: Array<{ id: string; anchor: 'positive' | 'negative' }>;
  safetyFailures: Array<{ id: string; reason: string }>;
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityAggregateCase[];
  interpretation: string;
}

export interface ReliabilityAggregateCase {
  id: string;
  anchor: 'positive' | 'negative' | null;
  safety: boolean;
  status: 'complete';
  passedTrials: number;
  k: number;
  passK: boolean;
  passAtK: boolean;
  flake: boolean;
  firstTrialStatus: TrialStatus | null;
  trials: ReliabilityTrial[];
  reason: string | null;
}

export function aggregateReliability(caseResults: ReliabilityCase[], options?: ReliabilityOptions): ReliabilityAggregate;
export function evaluateReliabilityGate(caseResults: ReliabilityCase[], options?: ReliabilityOptions): ReliabilityAggregate;
export const INCOMPLETE_TRIAL_STATUSES: readonly TrialStatus[];

