export type TrialOutcome = 'pass' | 'reject' | 'unknown';

export interface ReliabilityTrial {
  status: TrialStatus;
  outcome?: TrialOutcome;
  reason?: string | null;
}

export interface ReliabilityCase {
  id: string;
  anchor?: 'positive' | 'negative' | null;
  safety?: boolean;
  status?: TrialStatus;
  reason?: string | null;
  trials?: ReliabilityTrial[];
}

export interface ReliabilityOptions {
  k?: number;
  minCases?: number;
  maxFlakeRate?: number;
}

export interface ReliabilityAggregate {
  design: { k: number; minCases: number; maxFlakeRate: number };
  raw: { caseCount: number; completeCaseCount: number; incompleteCaseCount: number; incompleteCounts: Record<'missing' | 'timeout' | 'crash' | 'skip', number>; trialsObserved: number };
  metrics: { passK: number; passAtK: number; flakeRate: number; passKCount: number; passAtKCount: number; flakeCount: number };
  denominators: { passK: number; passAtK: number; flake: number };
  incomplete: Array<{ id: string; status: TrialStatus; reason: string | null }>;
  incompleteCounts: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
  anchors: { positive: ReliabilityAggregateCase[]; negative: ReliabilityAggregateCase[] };
  anchorFailures: Array<{ id: string; anchor: 'positive' | 'negative' }>;
  safetyFailures: Array<{ id: string; reason: string }>;
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityAggregateCase[];
  interpretation: string;
}

export interface ReliabilityAggregateCase {
  id: string;
  anchor: 'positive' | 'negative' | null;
  safety: boolean;
  status: 'complete';
  passedTrials: number;
  k: number;
  passK: boolean;
  passAtK: boolean;
  flake: boolean;
  firstTrialStatus: TrialStatus | null;
  trials: ReliabilityTrial[];
  reason: string | null;
}

export function aggregateReliability(caseResults: ReliabilityCase[], options?: ReliabilityOptions): ReliabilityAggregate;
export function evaluateReliabilityGate(caseResults: ReliabilityCase[], options?: ReliabilityOptions): ReliabilityAggregate;
export const INCOMPLETE_TRIAL_STATUSES: readonly TrialStatus[];
