const FAIL = 'fail';
const INCOMPLETE_STATUSES = new Set(['missing', 'timeout', 'crash', 'skip']);

function isIncomplete(status) {
  return INCOMPLETE_STATUSES.has(status);
}

function isSuccess(trial) {
  return trial?.status === PASS && trial?.outcome === 'pass';
}

function isExpectedSuccess(trial, anchor) {
  if (anchor === 'negative') return trial?.status === PASS && trial?.outcome === 'reject';
  return isSuccess(trial);
}

function emptyCounts() {
  return { missing: 0, timeout: 0, crash: 0, skip: 0 };
}

function classifyIncomplete(caseResult, counts) {
  const status = caseResult?.status;
  if (isIncomplete(status)) {
    counts[status] += 1;
    return true;
  }
  return false;
}

/**
 * Aggregates deterministic trial records. A complete case has exactly k trials.
 * Incomplete cases remain visible in the output but are excluded from metric
 * denominators. pass^k and pass@k intentionally have separate names.
 */
export function aggregateReliability(caseResults, options = {}) {
  const k = options.k ?? 3;
  const minCases = options.minCases ?? 20;
  const maxFlakeRate = options.maxFlakeRate ?? 0;
  if (!Number.isInteger(k) || k < 1) throw new TypeError('k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 0) throw new TypeError('minCases must be a non-negative integer');
  if (typeof maxFlakeRate !== 'number' || maxFlakeRate < 0 || maxFlakeRate > 1) {
    throw new TypeError('maxFlakeRate must be between 0 and 1');
  }

  const incompleteCounts = emptyCounts();
  const incompleteCases = [];
  const completeCases = [];
  const anchorResults = { positive: [], negative: [] };
  const safetyResults = [];

  for (const item of caseResults ?? []) {
    const id = item?.id ?? '<unknown>';
    if (classifyIncomplete(item, incompleteCounts)) {
      incompleteCases.push({ id, status: item.status, reason: item.reason ?? null });
      continue;
    }

    const trials = Array.isArray(item.trials) ? item.trials : [];
    if (trials.length !== k) {
      incompleteCounts.missing += 1;
      incompleteCases.push({ id, status: 'missing', reason: `expected ${k} trials, received ${trials.length}` });
      continue;
    }

    const passedTrials = trials.filter(isSuccess).length;
    const allPassed = passedTrials === k;
    const anyPassed = passedTrials > 0;
    const firstFailed = trials[0]?.status === FAIL;
    const laterPassed = trials.slice(1).some(isSuccess);
    const flake = firstFailed && laterPassed;
    const anchor = item.anchor ?? null;
    const safety = item.safety === true;
    const anchorPassed = anchor === null || trials.every((trial) => isExpectedSuccess(trial, anchor));

