      id,
      anchor,
      safety,
      status: 'complete',
      passedTrials,
      k,
      passK: allPassed,
      passAtK: anyPassed,
      flake,
      firstTrialStatus: trials[0]?.status ?? null,
      trials,
      reason: allPassed ? null : 'not all trials passed',
