    anchorFailures,
    safetyFailures,
    gate,
    reasons,
    cases: completeCases,
    interpretation: 'Deterministic fixture oracle only; not a claim about real-provider, human, or generalization performance.',
  };
}

function trialsHonorAnchor(item, anchor) {
  return item.trials.every((trial) => isExpectedSuccess(trial, anchor));
